rule_text:
rule MSSP_T1003_001_LSASS_Dump_File_Artifact {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "Critical"
    description = "Detects creation of a memory dump file whose name or path pattern is consistent with LSASS process memory dumping. Attackers using procdump, comsvcs.dll MiniDump, Task Manager, or custom tooling all produce a dump artifact on disk. This rule targets the resulting file artifact rather than the process invocation, providing coverage orthogonal to command-line detections."
    mitre_tactic = "Credential Access"
    mitre_technique = "T1003.001"
    mitre_technique_name = "OS Credential Dumping: LSASS Memory"
    log_prerequisites = "Requires EDR or Sysmon file-creation telemetry (Sysmon Event ID 11 or equivalent EDR file event) normalised into Chronicle UDM FILE_CREATION events with target.file.full_path populated."
    platform = "Windows"
    log_source = "windows_endpoint"
    false_positives = "Legitimate crash dump collection by Windows Error Reporting (WerFault.exe) writing to C:\\ProgramData\\Microsoft\\Windows\\WER\\; authorised memory forensics by incident responders; some AV/EDR self-diagnostic dumps. Tune using %lsass_dump_approved_paths and %lsass_dump_approved_writers."
    tuning_guidance = "Add approved dump output directories (e.g. WER default paths, IR tooling staging directories) to %lsass_dump_approved_paths. Add approved writer process paths (e.g. authorised IR tooling) to %lsass_dump_approved_writers. Consider narrowing to high-value asset groups first."

  events:
    $file.metadata.event_type = "FILE_CREATION"

    // Match dump file extensions commonly produced by LSASS dumping techniques
    // .dmp  - procdump, comsvcs MiniDump, Task Manager, WerFault
    // .mdmp - minidump variant used by some tooling
    // .bin  - raw dump variant used by some custom loaders
    (
      $file.target.file.full_path = /\.dmp$/ nocase or
      $file.target.file.full_path = /\.mdmp$/ nocase
    )

    // The dump file name or path must reference lsass, or the writing process
    // must be accessing lsass-related context. We match on filename containing
    // "lsass" OR on the writing process being a known dump-capable binary
    // writing to a non-standard (non-WER) location.
    // Condition A: filename itself contains "lsass"
    // Condition B: dump written by a process that has no legitimate reason to
    //              produce minidumps (e.g. rundll32, powershell, wscript, cscript,
    //              mshta, regsvr32, wmic) - these are LOLBins abused for dumping
    (
      $file.target.file.full_path = /lsass/ nocase or
      $file.principal.process.file.full_path = /\\(rundll32|powershell|pwsh|wscript|cscript|mshta|regsvr32|wmic|msiexec|certutil)\.exe$/ nocase
    )

    // Exclude known-good WER staging directories where Windows legitimately
    // writes crash dumps - these are handled by %lsass_dump_approved_paths
    not $file.target.file.full_path = /\\Windows\\(Temp|System32\\config\\systemprofile)\\/ nocase
    not $file.target.file.full_path = /\\ProgramData\\Microsoft\\Windows\\WER\\/ nocase

    // Reference-list exclusions for MSSP multi-tenant tuning
    not $file.target.file.full_path in %lsass_dump_approved_paths
    not $file.principal.process.file.full_path in %lsass_dump_approved_writers

  outcome:
    $risk_score = max(90)
    $mitre_technique_id = array_distinct("T1003.001")
    $primary_entity = array_distinct($file.principal.hostname)
    $dump_file_path = array_distinct($file.target.file.full_path)
    $writing_process = array_distinct($file.principal.process.file.full_path)
    $writing_user = array_distinct($file.principal.user.userid)

  condition:
    $file
}

rule MSSP_T1055_002_PE_Injection_Process_Handle_Open {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a non-system process opening a handle to a remote process with permissions consistent with PE injection (PROCESS_VM_WRITE + PROCESS_CREATE_THREAD). PE injection requires writing a PE image into the target address space and then creating a remote thread to execute it. Monitoring PROCESS_OPEN events for this access-right combination catches the injection setup before the payload executes, regardless of what tool or filename the attacker uses."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.002"
    mitre_technique_name = "Process Injection: Portable Executable Injection"
    log_prerequisites = "Requires EDR or Sysmon (Event ID 10 - ProcessAccess) telemetry normalised to UDM PROCESS_OPEN with target.process.access_mask populated. CrowdStrike, SentinelOne, and Microsoft Defender for Endpoint all emit equivalent telemetry."
    platform = "Windows"
    log_source = "windows_endpoint"
    false_positives = "Debuggers (WinDbg, x64dbg, Visual Studio), legitimate process-injection frameworks used by AV/EDR vendors themselves, RMM agents that perform live memory inspection, and some game anti-cheat engines."
    tuning_guidance = "Add known-good parent process paths (e.g. debuggers, AV engines, RMM agents) to %global_allowed_process_handle_openers. Narrow further by excluding self-injection (principal.process.pid = target.process.pid) if your EDR surfaces that field. Consider raising severity to Critical when the target process is a high-value host such as lsass.exe or winlogon.exe."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Caller must not be a known Windows system binary.
    // System processes live under System32 / SysWOW64 / WinSxS.
    not $open.principal.process.file.full_path = /\\(system32|syswow64|winsxs)\\/i nocase

    // Exclude the idle/system pseudo-process (PID 0/4) acting as caller.
    not $open.principal.process.file.full_path = /\\ntoskrnl\.exe$/ nocase

    // Target must be a real user-mode process (not the kernel pseudo-process).
    $open.target.process.file.full_path = /\.exe$/ nocase

    // Access mask 0x1fffff = PROCESS_ALL_ACCESS; also catch the minimal
    // combination required for PE injection:
    //   0x0020 = PROCESS_VM_WRITE
    //   0x0002 = PROCESS_CREATE_THREAD
    //   0x0008 = PROCESS_VM_OPERATION (needed for VirtualAllocEx)
    // EDRs typically log the decimal or hex access mask in the access_mask field.
    // Match the hex patterns most commonly emitted for injection-capable handles.
    (
      $open.target.process.access_mask = /0x1f0fff/ nocase or
      $open.target.process.access_mask = /0x1fffff/ nocase or
      $open.target.process.access_mask = /0x043[aA]/ nocase or
      $open.target.process.access_mask = /0x0[0-9a-fA-F]*[2-9a-fA-F][0-9a-fA-F]{2}[2-9a-fA-F][0-9a-fA-F]/ nocase
    )

    // Exclude callers explicitly allow-listed by the MSSP or client.
    not $open.principal.process.file.full_path in %global_allowed_process_handle_openers

    // Exclude self-opens where the process inspects its own memory (benign).
    not $open.principal.process.file.full_path = $open.target.process.file.full_path

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.002")
    $primary_entity = array_distinct($open.principal.hostname)
    $caller_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $access_mask_observed = array_distinct($open.target.process.access_mask)

  condition:
    $open
}

rule MSSP_T1055_002_PE_Injection_OpenThenRemoteThread {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Sequence"
    severity        = "Critical"
    description     = "Detects a two-stage PE injection pattern: a non-system process opens a handle to a remote process (PROCESS_OPEN) and then a new thread is created in that remote process context (PROCESS_LAUNCH of a remote thread surrogate). This covers the VirtualAllocEx/WriteProcessMemory/CreateRemoteThread injection chain without relying on command-line strings, providing additive coverage beyond existing PROCESS_LAUNCH command-line rules."
    mitre_tactic    = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.002"
    mitre_technique_name = "Process Injection: Portable Executable Injection"
    log_prerequisites = "Requires EDR or Sysmon telemetry that emits PROCESS_OPEN events (Sysmon Event ID 10) and PROCESS_LAUNCH events with parent/child process lineage. Both event types must be normalised into Chronicle UDM."
    platform        = "Windows"
    log_source      = "windows_endpoint"
    false_positives = "Debuggers (Visual Studio, WinDbg), legitimate AV/EDR self-protection, JIT compilers (JVM, .NET CLR), RMM agents performing process inspection, software installers that inject into running processes."
    tuning_guidance = "Add known-good injecting processes (debuggers, AV engines, RMM agents) to %global_allowed_process_open_sources. Add known-good target processes to %global_allowed_injection_targets. Narrow the rule further by restricting $open.target.process.file.full_path to high-value targets such as lsass.exe or svchost.exe if noise is excessive."

  events:
    // Stage 1: A non-system process opens a handle to a remote process.
    // Sysmon Event ID 10 maps to PROCESS_OPEN in UDM.
    // We filter to suspicious openers - processes NOT residing in System32/SysWOW64
    // that open handles to other processes, which is the precursor to PE injection.
    $open.metadata.event_type = "PROCESS_OPEN"
    // Opener must NOT be a known system binary location
    not $open.principal.process.file.full_path = /\\(Windows\\System32|Windows\\SysWOW64|Windows\\WinSxS)\\/ nocase
    // Opener must NOT be a known browser or benign process path - handled via reference list
    not $open.principal.process.file.full_path in %global_allowed_process_open_sources
    // Target of the open must be a running process (has a path populated)
    $open.target.process.file.full_path = /\.exe$/ nocase
    // Exclude self-opens (process opening itself is benign)
    $open.principal.process.pid != $open.target.process.pid
    // Join key: the hostname where both events occur
    $open.principal.hostname = $hostname
    // Capture the opener PID to correlate with the subsequent injection event
    $open.principal.process.pid = $injector_pid

    // Stage 2: Within the time window, a new process/thread is launched
    // whose PARENT is the same process that performed the PROCESS_OPEN.
    // CreateRemoteThread causes the remote process to spawn execution;
    // EDR telemetry surfaces this as a PROCESS_LAUNCH with the injector as parent.
    $launch.metadata.event_type = "PROCESS_LAUNCH"
    // The parent of the newly launched execution context is the injector
    $launch.principal.process.pid = $injector_pid
    $launch.principal.hostname = $hostname
    // The child process must not be a known-good child of the opener
    not $launch.target.process.file.full_path in %global_allowed_injection_targets
    // Exclude common benign parent-child patterns: parent in System32 already excluded above
    not $launch.target.process.file.full_path = /\\(conhost|WerFault|werfaultsecure)\.exe$/ nocase

    // Chronological ordering: open handle before remote thread creation
    $open.metadata.event_timestamp.seconds <= $launch.metadata.event_timestamp.seconds

  match:
    $hostname, $injector_pid over 5m

  outcome:
    $risk_score = max(90)
    $mitre_technique_id = array_distinct("T1055.002")
    $primary_entity = array_distinct($open.principal.hostname)
    $injecting_process = array_distinct($open.principal.process.file.full_path)
    $target_process_opened = array_distinct($open.target.process.file.full_path)
    $spawned_child_process = array_distinct($launch.target.process.file.full_path)
    $spawned_child_cmdline = array_distinct($launch.target.process.command_line)
    $affected_user = array_distinct($open.principal.user.userid)

  condition:
    $open and $launch
}

rule MSSP_T1055_005_TLS_Injection_Process_Handle_Request {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Single-Event"
    severity        = "High"
    description     = "Detects a suspicious process opening a handle to a remote process with permissions consistent with TLS callback injection (VM_WRITE + VM_OPERATION + CREATE_THREAD). Attackers manipulate PE TLS callback pointers in a target process's memory space before the legitimate entry point executes. This rule pivots on the PROCESS_OPEN event produced by EDR/Sysmon rather than command-line telemetry, providing additive coverage over process-creation rules."
    mitre_tactic    = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.005"
    mitre_technique_name = "Process Injection: Thread Local Storage"
    log_prerequisites = "Requires EDR or Sysmon (Event ID 10 - ProcessAccess) telemetry normalised into UDM PROCESS_OPEN events with target.process.file.full_path and principal.process.file.full_path populated. Access rights bitmask should be present in security_result.description or equivalent normalised field."
    platform        = "Windows"
    log_source      = "windows_endpoint"
    false_positives = "Legitimate debuggers (WinDbg, x64dbg), profilers (VTune, dotTrace), AV/EDR self-protection modules, JIT compilers (CLR, JVM), and some RMM agents that perform cross-process memory operations."
    tuning_guidance = "Add known-good parent process paths (debuggers, profilers, AV engines) to %global_allowed_process_open_sources. Narrow further by restricting to high-value target processes (lsass.exe, svchost.exe) if noise is high. Consider pairing with a FILE_CREATION rule (variant 2) for PE artifacts with TLS directory entries."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Suspicious openers: scripting hosts, document readers, and generic
    // loader processes that have no legitimate reason to write into a
    // remote process's memory space. Regex targets the filename only so
    // renamed binaries in unusual paths are still caught.
    $open.principal.process.file.full_path = /\\(powershell|pwsh|wscript|cscript|mshta|rundll32|regsvr32|msiexec|wmic|certutil|bitsadmin|explorer|cmd)\.exe$/ nocase

    // Target must be a long-running host process whose TLS callbacks
    // execute early in the process lifecycle - prime candidates for
    // TLS callback hijacking.
    $open.target.process.file.full_path = /\\(svchost|lsass|spoolsv|services|winlogon|csrss|dllhost|taskhost|taskhostw|RuntimeBroker|SearchIndexer|SearchHost|sihost|fontdrvhost)\.exe$/ nocase

    // The opener must NOT be the same image as the target (self-open is
    // normal for some processes and is not indicative of injection).
    // We enforce this by requiring the principal path does NOT match the
    // target path pattern - expressed as a negative regex on the principal
    // to exclude cases where the same binary opens itself.
    not $open.principal.process.file.full_path = /\\(svchost|lsass|spoolsv|services|winlogon|csrss|dllhost|taskhost|taskhostw|RuntimeBroker|SearchIndexer|SearchHost|sihost|fontdrvhost)\.exe$/ nocase

    // Exclude known-good administrative and security tooling paths
    // populated per-customer via reference list.
    not $open.principal.process.file.full_path in %global_allowed_process_open_sources

    // Exclude standard Windows system directories for the opener -
    // legitimate system-to-system opens from System32 are expected;
    // openers from user-writable or temp paths are suspicious.
    // We require the opener to NOT originate from the canonical system path.
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww][Ii][Nn][Dd][Oo][Ww][Ss]\\[Ss][Yy][Ss][Tt][Ee][Mm]32\\/ nocase

  outcome:
    $risk_score        = max(80)
    $mitre_technique_id = array_distinct("T1055.005")
    $primary_entity    = array_distinct($open.principal.hostname)
    $opener_process    = array_distinct($open.principal.process.file.full_path)
    $target_process    = array_distinct($open.target.process.file.full_path)
    $opener_pid        = array_distinct($open.principal.process.pid)
    $target_pid        = array_distinct($open.target.process.pid)

  condition:
    $open
}

rule MSSP_T1055_008_Ptrace_Injection_Proc_Mem_Write {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Single-Event"
    severity        = "High"
    description     = "Detects file-level access to /proc/<pid>/mem or /proc/<pid>/task paths that indicate a process is writing directly into another process's address space - the artifact produced by ptrace-based injection. Legitimate debuggers (gdb, strace) access these paths, but access from non-debugging binaries or from processes running out of world-writable directories is highly suspicious. This rule targets the resulting file-system state change rather than the ptrace syscall itself, providing coverage that evades command-line-only detections."
    mitre_tactic    = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.008"
    mitre_technique_name = "Process Injection: Ptrace System Calls"
    log_prerequisites = "Requires Linux EDR or auditd with file-open/write auditing enabled for /proc filesystem paths. Auditd rule: -a always,exit -F arch=b64 -S open,openat,write -F dir=/proc -F key=ptrace_mem_write. EDR agents that emit FILE_MODIFICATION events for /proc/<pid>/mem also satisfy this requirement."
    platform        = "Linux"
    log_source      = "linux_endpoint"
    false_positives = "GDB, strace, ltrace, and other legitimate debuggers; Java/JVM JIT compilers; some profiling agents (perf, valgrind); container runtimes performing checkpoint/restore (CRIU). Tune by adding known debugger and profiler paths to %linux_allowed_proc_mem_writers."
    tuning_guidance = "Populate %linux_allowed_proc_mem_writers with full paths of approved debuggers and profiling tools (e.g. /usr/bin/gdb, /usr/bin/strace, /usr/bin/valgrind). Consider also excluding CI/CD build hosts by hostname if they run heavy profiling workloads. Raise severity to Critical if the writing process originates from /tmp, /dev/shm, or /var/tmp."

  events:
    $file.metadata.event_type = "FILE_MODIFICATION"

    // Target must be the /proc/<numeric-pid>/mem pseudo-file or adjacent
    // writable task-memory paths that ptrace injection tools access.
    // Numeric PID segment ensures we match real process entries, not /proc/sys.
    $file.target.file.full_path = /\/proc\/[0-9]+\/(mem|task\/[0-9]+\/mem)$/ nocase

    // The writing process must NOT be a known legitimate debugger/profiler.
    not $file.principal.process.file.full_path in %linux_allowed_proc_mem_writers

    // Exclude kernel threads (no user-space path) - they appear as empty strings.
    $file.principal.process.file.full_path != ""

    // Heighten signal: flag writes originating from world-writable or
    // temporary staging directories commonly used by malware droppers.
    // This is an OR-style broadening filter kept as a separate positive match
    // so the rule fires on ANY /proc/*/mem write not in the allow-list,
    // while the outcome score escalates for high-risk source paths.
    $file.principal.hostname = $host

  outcome:
    // Base risk 70; escalate to 95 when the writing process lives in a
    // world-writable directory - a strong indicator of a dropped payload.
    $risk_score = max(
      if($file.principal.process.file.full_path = /^\/(tmp|dev\/shm|var\/tmp|run\/shm)\//, 95, 70)
    )
    $mitre_technique_id = array_distinct("T1055.008")
    $primary_entity     = array_distinct($file.principal.hostname)
    $injecting_process  = array_distinct($file.principal.process.file.full_path)
    $target_mem_path    = array_distinct($file.target.file.full_path)
    $acting_user        = array_distinct($file.principal.user.userid)

  condition:
    $file
}

rule MSSP_T1055_011_EWM_Injection_Process_Handle_Request {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a non-privileged or unexpected process opening a handle to a remote process with VM_WRITE and VM_OPERATION access rights, which is a prerequisite for Extra Window Memory (EWM) injection. Attackers write shellcode into a shared section of the target process memory, then redirect execution via the EWM pointer. This rule targets the PROCESS_OPEN state-change artifact rather than command-line telemetry, providing additive coverage over process-creation rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.011"
    mitre_technique_name = "Process Injection: Extra Window Memory Injection"
    log_prerequisites = "Requires EDR or Sysmon (Event ID 10 - ProcessAccess) telemetry normalised into UDM PROCESS_OPEN events, including target.process.file.full_path, principal.process.file.full_path, and target.process.access_mask or equivalent access rights field."
    platform = "Windows"
    log_source = "windows_endpoint"
    false_positives = "Legitimate debuggers (WinDbg, x64dbg), profilers, AV/EDR self-protection, RMM agents performing process inspection, software installers that inject into explorer.exe for shell extensions."
    tuning_guidance = "Add known-good parent process paths (e.g., EDR agent, AV scanner, approved RMM) to %global_allowed_process_open_sources. Narrow scope by excluding processes signed by trusted vendors if your EDR surfaces code-signing data. Consider pairing with a network or file-creation rule for the same host within a short window."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Target must be a GUI-capable Windows process that hosts window classes
    // (explorer, svchost, or any process that registers window classes)
    // We match broadly on Windows system processes that own message queues
    $open.target.process.file.full_path = /\\(explorer|svchost|RuntimeBroker|dwm|taskhostw|sihost|ctfmon|SearchHost|ShellExperienceHost|StartMenuExperienceHost)\.exe$/ nocase

    // Principal (requesting process) must NOT itself be a known system binary
    // performing legitimate cross-process operations
    not $open.principal.process.file.full_path = /\\(svchost|lsass|csrss|wininit|services|smss|winlogon|MsMpEng|SenseIR|SenseCE|MsSense|CylanceSvc|CrowdStrike|elastic-endpoint)\.exe$/ nocase

    // Principal must not be a known debugger or profiler
    not $open.principal.process.file.full_path = /\\(windbg|devenv|msvsmon|perfmon|procexp|procexp64|procmon|procmon64|x64dbg|x32dbg|ollydbg|ida|ida64)\.exe$/ nocase

    // Exclude processes launching from standard Windows system directories
    // to reduce noise from legitimate OS cross-process activity;
    // suspicious openers typically live outside System32/SysWOW64
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww][Ii][Nn][Dd][Oo][Ww][Ss]\\[Ss]ystem32\\/ nocase
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww][Ii][Nn][Dd][Oo][Ww][Ss]\\[Ss]ys[Ww][Oo][Ww]64\\/ nocase

    // Exclude processes from Program Files (signed vendor software)
    not $open.principal.process.file.full_path = /^[Cc]:\\[Pp]rogram [Ff]iles/ nocase

    // Exclude processes from known-good admin tool list (MSSP tuning list)
    not $open.principal.process.file.full_path in %global_allowed_process_open_sources

    // Require a valid principal hostname to anchor the alert to an asset
    $open.principal.hostname != ""

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1055.011")
    $primary_entity = array_distinct($open.principal.hostname)
    $requesting_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)

  condition:
    $open
}

rule MSSP_T1055_012_Process_Hollowing_Suspended_Process_Handle {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects PROCESS_OPEN events where a process acquires a handle to another process with full access rights consistent with process hollowing: a suspended victim process is opened so its memory can be unmapped and replaced. EDR/Sysmon telemetry surfaces these handle requests as PROCESS_OPEN events with broad access masks. This rule targets the handle-acquisition layer rather than command-line arguments, providing coverage orthogonal to process-creation rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.012"
    mitre_technique_name = "Process Injection: Process Hollowing"
    log_prerequisites = "Requires EDR or Sysmon (Event ID 10 - ProcessAccess) telemetry normalised into Chronicle UDM PROCESS_OPEN events. The access mask field must be populated. Sysmon must be configured to log ProcessAccess events for broad access masks (e.g., 0x1fffff, 0x1f0fff, 0x001f0fff)."
    platform = "Windows"
    log_source = "windows_endpoint"
    false_positives = "Legitimate debuggers (Visual Studio, WinDbg), process monitoring tools (Process Explorer, Process Hacker), AV/EDR self-inspection, software installers that inject into their own child processes, JIT compilers."
    tuning_guidance = "Add known-good opener process paths to %global_allowed_process_openers (e.g., debuggers, AV engines). Add known-good victim process paths to %global_allowed_hollow_targets if specific system binaries generate noise. Narrow the access mask filter if your EDR populates that field consistently."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opening (injecting) process must NOT be a known system process
    // that legitimately opens children with full access.
    // Target well-known hollowing launchers by excluding trusted system paths
    // while keeping the rule rename-resilient via regex on path structure.
    not $open.principal.process.file.full_path = /\\Windows\\System32\\(lsass|csrss|smss|wininit|services|svchost)\.exe$/ nocase
    not $open.principal.process.file.full_path = /\\Windows\\SysWOW64\\(lsass|csrss|smss|wininit|services|svchost)\.exe$/ nocase

    // Victim process is a legitimate Windows binary - hollowing typically
    // targets trusted executables to inherit their reputation/context.
    // Match common hollowing targets: any .exe under System32 or SysWOW64,
    // or any .exe under Program Files, or any .exe under the user profile.
    (
      $open.target.process.file.full_path = /\\Windows\\(System32|SysWOW64)\\[^\\]+\.exe$/ nocase
      or
      $open.target.process.file.full_path = /\\Program Files[^\\]*\\[^\\]+\.exe$/ nocase
    )

    // The opener must NOT be the same binary as the target (self-open is normal
    // for some runtimes; cross-binary full-access open is the suspicious signal).
    // We cannot compare two fields directly in YARA-L, so we exclude the
    // exact self-open pattern for the most common false-positive: svchost->svchost.
    not $open.principal.process.file.full_path = /\\svchost\.exe$/ nocase

    // Exclude known-good opener tools via reference list for MSSP tuning.
    not $open.principal.process.file.full_path in %global_allowed_process_openers

    // Exclude known-good target processes that are routinely opened by
    // legitimate software (e.g., explorer.exe by shell extensions).
    not $open.target.process.file.full_path in %global_allowed_hollow_targets

    // The opener process must not reside in a trusted system directory itself,
    // which would indicate a legitimate OS component performing the open.
    not $open.principal.process.file.full_path = /^[Cc]:\\Windows\\(System32|SysWOW64|WinSxS|servicing)\\/ nocase

    // Opener must be running from a user-writable or suspicious location,
    // which is characteristic of hollowing stagers dropped by malware.
    (
      $open.principal.process.file.full_path = /^[Cc]:\\Users\\[^\\]+\\(AppData|Downloads|Desktop|Temp|Documents)/ nocase
      or
      $open.principal.process.file.full_path = /^[Cc]:\\(ProgramData|Temp|Windows\\Temp)\\/ nocase
      or
      $open.principal.process.file.full_path = /^[Cc]:\\(Perflogs|Recovery|Intel)\\/ nocase
    )

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.012")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opener_user = array_distinct($open.principal.user.userid)

  condition:
    $open
}

rule MSSP_T1055_012_Hollowed_Process_Anomalous_Network_Connection {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Sequence"
    severity        = "High"
    description     = "Detects a process hollowing indicator sequence: a legitimate Windows host process is launched in a suspended-then-resumed pattern (evidenced by an unusual parent) and subsequently makes an outbound network connection. Process hollowing replaces the memory of a legitimate process with malicious code; the hollowed process then communicates externally while appearing benign. This rule joins the anomalous process launch to the subsequent network connection over a 5-minute window."
    mitre_tactic    = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.012"
    mitre_technique_name = "Process Injection: Process Hollowing"
    log_prerequisites = "Requires EDR or Sysmon process-launch telemetry (including parent process lineage) and network connection telemetry normalised into UDM PROCESS_LAUNCH and NETWORK_CONNECTION events."
    platform        = "Windows"
    log_source      = "windows_endpoint"
    false_positives = "Legitimate software updaters or installers that spawn svchost/RuntimeBroker as a child and then phone home; JVM/CLR runtimes hosting child processes; some RMM agents. Tune via %hollowing_allowed_parent_processes and %hollowing_allowed_child_destinations."
    tuning_guidance = "Add known-good parent process paths (e.g. service control manager, approved deployment tools) to %hollowing_allowed_parent_processes. Add approved internal CIDR ranges or trusted update endpoints to %hollowing_allowed_child_destinations. Narrow the target process list if the environment does not use all listed binaries."

  events:
    // Event 1: A canonical Windows host process is spawned by an unusual parent.
    // Legitimate hollowing targets are typically svchost, RuntimeBroker, dllhost,
    // werfault, msiexec, or similar trusted binaries. When hollowed, they are
    // commonly launched by non-service-control-manager parents (e.g. user-space
    // processes, scripting engines, or other executables that would not normally
    // spawn these binaries).
    $proc.metadata.event_type = "PROCESS_LAUNCH"
    $proc.target.process.file.full_path = /\\(svchost|RuntimeBroker|dllhost|WerFault|msiexec|wuauclt|SearchIndexer|spoolsv|lsass|taskhost|taskhostw)\.exe$/ nocase
    // Parent must NOT be a known legitimate service launcher
    not $proc.principal.process.file.full_path = /\\(services|svchost|smss|wininit|winlogon|MsMpEng|TiWorker|TrustedInstaller|msiexec|explorer)\.exe$/ nocase
    // Exclude known-good parent paths supplied via reference list
    not $proc.principal.process.file.full_path in %hollowing_allowed_parent_processes
    // Bind the hostname for the join
    $proc.principal.hostname = $hostname
    // Bind the child process image path so we can correlate to the network event
    $proc.target.process.file.full_path = $child_image

    // Event 2: The same hollowed-looking process makes an outbound network connection
    // on the same host within the time window.
    $net.metadata.event_type = "NETWORK_CONNECTION"
    // The process making the connection matches the child image from Event 1
    $net.principal.process.file.full_path = $child_image
    // Must be an external (non-loopback) destination - filter RFC1918 and loopback
    not $net.target.ip in %rfc1918_internal
    not $net.target.ip = "127.0.0.1"
    not $net.target.ip = "::1"
    not $net.target.ip in %hollowing_allowed_child_destinations
    // Bind hostname for join
    $net.principal.hostname = $hostname

    // Chronological ordering: process launch must precede the network connection
    $proc.metadata.event_timestamp.seconds <= $net.metadata.event_timestamp.seconds

  match:
    $hostname, $child_image over 5m

  outcome:
    $risk_score          = max(85)
    $mitre_technique_id  = array_distinct("T1055.012")
    $primary_entity      = array_distinct($proc.principal.hostname)
    $hollowed_process    = array_distinct($child_image)
    $parent_process      = array_distinct($proc.principal.process.file.full_path)
    $destination_ips     = array_distinct($net.target.ip)
    $destination_ports   = array_distinct($net.target.port)

  condition:
    $proc and $net
}

rule MSSP_T1055_013_Doppelganging_Process_Handle_Open {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Single-Event"
    severity        = "Critical"
    description     = "Detects process handle requests consistent with Process Doppelgänging. The technique requires a process to open a handle to a legitimate executable on disk using TxF semantics, then map a modified (malicious) section into memory. At the EDR telemetry layer this surfaces as a PROCESS_OPEN event where a non-system, non-security process opens a handle to a well-known Windows system binary with access rights that include VM_WRITE or PROCESS_VM_WRITE combined with PROCESS_CREATE_THREAD - the combination needed to inject and execute code in the target process. Detecting the handle request rather than the command line provides coverage that survives binary renaming and command-line obfuscation."
    mitre_tactic    = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.013"
    mitre_technique_name = "Process Injection: Process Doppelgänging"
    log_prerequisites = "Requires EDR or Sysmon telemetry that emits PROCESS_OPEN events with target process path and granted access mask. Sysmon Event ID 10 (ProcessAccess) maps to this UDM event type. CrowdStrike, SentinelOne, and Defender for Endpoint all emit equivalent telemetry normalised by Chronicle UDM."
    platform        = "Windows"
    log_source      = "windows_endpoint"
    false_positives = "Security tooling (AV, EDR agents themselves), debuggers (WinDbg, x64dbg), process monitoring utilities (Process Hacker, Process Monitor), legitimate software installers that patch in-memory, and JIT compilers. Exclude by principal process path using the reference list."
    tuning_guidance = "Populate %global_allowed_process_open_tools with full paths of approved security and developer tools (e.g. EDR agent binaries, debuggers). Narrow further by restricting target process paths to the Windows system32/syswow64 subtree if false-positive volume remains high. Consider pairing with a threshold rule to require multiple such opens from the same principal within a short window."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opener (principal) must NOT itself be a core Windows system process.
    // Doppelgänging requires a user-space loader process to open the target.
    // We exclude the canonical system process paths that legitimately open handles
    // to other processes as part of normal OS operation.
    not $open.principal.process.file.full_path = /\\(System32|SysWOW64)\\(lsass|csrss|smss|wininit|services|svchost|ntoskrnl)\.exe$/ nocase
    not $open.principal.process.file.full_path = /^$/ nocase

    // The target of the handle open must be a legitimate Windows executable.
    // Doppelgänging replaces the content of a real binary's TxF-transacted
    // handle, so the target is always a genuine PE on disk - typically a
    // system binary chosen to blend in with normal process lists.
    $open.target.process.file.full_path = /\\(Windows|System32|SysWOW64|WinSxS)\\.*\.exe$/ nocase

    // The principal process must not be a known Windows system binary itself.
    // Attackers use a custom loader, not a built-in tool, for this technique.
    not $open.principal.process.file.full_path = /\\Windows\\(System32|SysWOW64)\\.*\.exe$/ nocase

    // The principal must not be a known-good administrative or security tool.
    not $open.principal.process.file.full_path in %global_allowed_process_open_tools

    // The granted access mask field captures what rights were requested.
    // PROCESS_VM_WRITE (0x0020) | PROCESS_VM_OPERATION (0x0008) |
    // PROCESS_CREATE_THREAD (0x0002) is the canonical doppelgänging triplet.
    // Chronicle UDM surfaces this in target.process.access_mask (integer) or
    // as a string in security_result.description depending on the EDR.
    // We match on the string representation emitted by Sysmon / EDR normalisation.
    $open.target.process.command_line = /0x[0-9a-f]*(001f|0[02][0-9a-f]{2}|1fffff)/ nocase

  outcome:
    $risk_score        = max(90)
    $mitre_technique_id = array_distinct("T1055.013")
    $primary_entity    = array_distinct($open.principal.hostname)
    $opener_process    = array_distinct($open.principal.process.file.full_path)
    $target_process    = array_distinct($open.target.process.file.full_path)

  condition:
    $open
}

rule MSSP_T1055_015_ListPlanting_CrossProcess_Handle_Request {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Single-Event"
    severity        = "High"
    description     = "Detects a process opening a handle to another process with PROCESS_VM_WRITE or PROCESS_VM_OPERATION access rights, which is a prerequisite for ListPlanting. The attacker must copy shellcode into the target process address space before abusing the SysListView32 sort callback. This rule pivots on the cross-process handle acquisition (PROCESS_OPEN) rather than command-line arguments, providing a lower-evasion-surface detection layer. Suspicious combinations are: a non-system process opening a handle to a process it did not spawn, with write-capable access rights."
    mitre_tactic    = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.015"
    mitre_technique_name = "Process Injection: ListPlanting"
    log_prerequisites = "Requires EDR or Sysmon Event ID 10 (ProcessAccess) telemetry normalised to UDM PROCESS_OPEN. The access mask field must be populated in target.process.access_mask or an equivalent UDM field. Sysmon must be configured with a ProcessAccess rule capturing GrantedAccess masks that include 0x0020 (PROCESS_VM_WRITE) or 0x0008 (PROCESS_VM_OPERATION)."
    platform        = "Windows"
    log_source      = "windows_endpoint"
    false_positives = "Debuggers (Visual Studio, WinDbg, x64dbg), legitimate memory-scanning AV/EDR self-protection, JVM/CLR runtimes performing cross-process heap inspection, RMM agents, crash-dump collectors (WerFault), and software installers that patch running processes."
    tuning_guidance = "Add known-good opener process paths to %global_allowed_vm_write_openers (e.g. debuggers, AV engines, RMM agents). Add known-good target process paths to %global_allowed_vm_write_targets. Narrow further by requiring the opener to be a user-space process (exclude paths under System32 and SysWOW64 for the opener if your EDR populates those reliably)."

  events:
    // PROCESS_OPEN corresponds to Sysmon Event 10 (ProcessAccess) in UDM.
    // principal = the process requesting the handle (opener / attacker process).
    // target    = the process whose handle is being acquired (victim process).
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opener must be a user-space process - not a Windows kernel/system path.
    // Legitimate ListPlanting openers will be attacker-controlled user processes.
    not $open.principal.process.file.full_path = /\\Windows\\System32\\/  nocase
    not $open.principal.process.file.full_path = /\\Windows\\SysWOW64\\/ nocase
    not $open.principal.process.file.full_path = /\\Windows\\WinSxS\\/   nocase

    // Target must be a process that hosts a SysListView32 control.
    // Common hosts: Explorer, taskmgr, mmc, regedit, and many third-party apps.
    // We match processes that are known to host list-view controls and are
    // attractive privilege-escalation targets.
    $open.target.process.file.full_path = /\\(explorer|taskmgr|mmc|regedit|control|rundll32|dllhost|svchost)\.exe$/ nocase

    // The opener must NOT be a child of the target (legitimate parent-child IPC).
    // We approximate this by requiring opener and target to be different processes
    // and that the opener is not a known system management binary.
    not $open.principal.process.file.full_path = /\\(taskmgr|procexp|procexp64|procmon|procmon64|perfmon|resmon)\.exe$/ nocase

    // Exclude known-good openers via reference list (MSSP multi-tenant tuning).
    not $open.principal.process.file.full_path in %global_allowed_vm_write_openers

    // Exclude known-good targets via reference list.
    not $open.target.process.file.full_path in %global_allowed_vm_write_targets

    // Capture the hostname for grouping and outcome.
    $open.principal.hostname = $hostname

  outcome:
    // Risk score reflects high-confidence cross-process write access to a
    // list-view-hosting process from an unexpected opener.
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.015")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opener_pid     = array_distinct($open.principal.process.pid)
    $target_pid     = array_distinct($open.target.process.pid)

  condition:
    $open
}

rule MSSP_T1059_009_SaaS_ServicePrincipal_API_Consent_Abuse {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a service principal or application identity being granted elevated permissions or new API consent scopes in an identity provider, which is a key enabler for Cloud API abuse (T1059.009). Adversaries who compromise or register a service principal can silently invoke cloud APIs at scale without interactive user sessions. This rule fires on permission-grant events from non-interactive, application-type principals, which is a state change produced by the abuse rather than a command-line invocation."
    mitre_tactic = "Execution"
    mitre_technique = "T1059.009"
    mitre_technique_name = "Command and Scripting Interpreter: Cloud API"
    log_prerequisites = "Requires identity provider audit logs normalised to UDM. Events must include USER_CHANGE_PERMISSIONS or GROUP_MODIFICATION for service principal / application objects. Entra ID audit category 'ApplicationManagement' and 'RoleManagement' are the primary sources."
    platform = "SaaS"
    log_source = "identity"
    false_positives = "Legitimate DevOps pipelines granting API permissions during CI/CD deployments; IT administrators provisioning new integrations; sanctioned ISV onboarding workflows."
    tuning_guidance = "Populate %allowed_service_principal_operators with the user IDs of approved DevOps service accounts and pipeline identities. Populate %allowed_admin_roles with role names that are expected to perform permission grants in your environment. Consider narrowing the match window or adding a secondary condition on the target role sensitivity."

  events:
    $auth.metadata.event_type = "USER_CHANGE_PERMISSIONS"

    // The actor performing the grant must be a non-interactive / application identity.
    // Service principals and managed identities typically carry an appid, client_id,
    // or similar token-based identifier rather than a human UPN.
    // We match on the absence of a human-style UPN suffix and presence of app-style identifiers.
    $auth.principal.user.userid = /^[0-9a-fA-F\-]{36}$/ nocase

    // The target object being granted permissions should be an application or service principal.
    // Identity providers surface these as resource types containing "application",
    // "serviceprincipal", or "approleassignment" in the resource name or path.
    $auth.target.resource.name = /application|serviceprincipal|approleassignment|oauth2permissiongrant/ nocase

    // Catch high-privilege API permission grants: roles that allow broad API execution.
    // These role/scope names are normalised across Entra ID and similar IdPs.
    (
      $auth.target.resource.attribute.roles.name = /directory\.readwrite|rolemanagement\.readwrite|application\.readwrite|allprincipal|full_?control|admin/ nocase
      or
      $auth.security_result.description = /admin consent|delegated permission|application permission|role assignment|scope grant/ nocase
    )

    // Exclude known-good pipeline operators and approved admin identities.
    not $auth.principal.user.userid in %allowed_service_principal_operators

    // Exclude expected administrative role names performing routine grants.
    not $auth.target.resource.attribute.roles.name in %allowed_admin_roles

  outcome:
    $risk_score = max(78)
    $mitre_technique_id = array_distinct("T1059.009")
    $primary_entity = array_distinct($auth.principal.user.userid)
    $granted_permission = array_distinct($auth.target.resource.attribute.roles.name)
    $target_application = array_distinct($auth.target.resource.name)

  condition:
    $auth
}

rule MSSP_T1071_001_CnC_Web_Protocol_Beaconing_Network {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Single-Event"
    severity        = "Medium"
    description     = "Detects potential C2 beaconing over HTTP/HTTPS from a Windows host observed at the firewall or proxy perimeter. Looks for high-port or non-standard-port outbound web connections to external destinations, which is characteristic of implants tunnelling C2 traffic over web protocols to blend with legitimate traffic. Internal destinations are excluded via reference list."
    mitre_tactic    = "Command and Control"
    mitre_technique = "T1071.001"
    mitre_technique_name = "Application Layer Protocol: Web Protocols"
    log_prerequisites = "Requires firewall or forward-proxy logs normalised into Chronicle UDM NETWORK_CONNECTION or NETWORK_HTTP events. Fields needed: principal.ip, target.ip, target.port, network.http.method, network.application_protocol."
    platform        = "Windows"
    log_source      = "firewall"
    false_positives = "Software update agents, telemetry clients, cloud sync tools, and monitoring agents that poll external endpoints on non-standard ports. RMM platforms (e.g., remote management agents) frequently generate similar patterns."
    tuning_guidance = "Add known-good external IPs or CIDR ranges to %global_allowed_external_web_destinations. Add sanctioned high-port SaaS endpoints to %global_allowed_nonstandard_web_ports. Narrow the port range if your environment standardises on 443/80 only."

  events:
    $net.metadata.event_type = "NETWORK_CONNECTION"

    // Outbound connection on a web-adjacent port that is NOT the standard
    // HTTP (80) or HTTPS (443) port. Adversaries frequently use alternate
    // ports (8080, 8443, 8888, 4443, 8000, 9443, etc.) to carry HTTP/S C2
    // traffic while still appearing as web protocol traffic.
    (
      $net.target.port = 8080 or
      $net.target.port = 8443 or
      $net.target.port = 8888 or
      $net.target.port = 4443 or
      $net.target.port = 8000 or
      $net.target.port = 9443 or
      $net.target.port = 8008 or
      $net.target.port = 8090
    )

    // Restrict to HTTP or HTTPS application protocol where the perimeter
    // device has identified the protocol layer (proxy/NGFW enrichment).
    // This prevents matching arbitrary high-port traffic unrelated to web.
    $net.network.application_protocol = /^https?$/ nocase

    // Source must be an RFC-1918 internal host (the Windows workstation/server).
    // We confirm it is internal by requiring it NOT be in the external list,
    // and separately exclude known-good external destinations.
    $net.principal.ip in %rfc1918_internal

    // Exclude sanctioned external destinations to reduce noise across tenants.
    not $net.target.ip in %global_allowed_external_web_destinations

    // Exclude connections whose destination port is explicitly approved
    // (e.g., a known SaaS product running on 8443).
    not $net.target.ip in %global_allowed_nonstandard_web_ports

  outcome:
    $risk_score        = max(55)
    $mitre_technique_id = array_distinct("T1071.001")
    $primary_entity    = array_distinct($net.principal.ip)
    $destination_ips   = array_distinct($net.target.ip)
    $destination_ports = array_distinct($net.target.port)

  condition:
    $net
}

rule MSSP_T1555_006_Cloud_Secrets_Manager_Bulk_Access {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects access to cloud secrets management stores (AWS Secrets Manager, GCP Secret Manager, Azure Key Vault) via cloud audit logs. Focuses on the API-level resource access event produced when a principal retrieves a secret value, which is the state-change artifact left behind regardless of how the access was initiated. Bulk or anomalous secret reads by a single identity are a strong indicator of credential harvesting."
    mitre_tactic = "Credential Access"
    mitre_technique = "T1555.006"
    mitre_technique_name = "Credentials from Password Stores: Cloud Secrets Management Stores"
    log_prerequisites = "Requires cloud provider audit logs normalised into Chronicle UDM: AWS CloudTrail (GetSecretValue, DescribeSecret), GCP Audit Logs (accessSecretVersion), Azure Activity Logs (SecretGet, GetSecret). Event type USER_RESOURCE_ACCESS."
    platform = "IaaS"
    log_source = "cloud_audit"
    false_positives = "Legitimate application service accounts performing scheduled secret rotation checks, CI/CD pipelines retrieving deployment credentials, authorised secrets scanning tools."
    tuning_guidance = "Add known-good service account identities (CI/CD, rotation agents) to %cloud_allowed_secrets_readers. Narrow target.resource.name regex to your naming convention for non-sensitive secret namespaces if needed. Consider pairing with a threshold rule to catch low-and-slow harvesting."

  events:
    $cloud.metadata.event_type = "USER_RESOURCE_ACCESS"

    // Match the normalised API operation names across AWS, GCP, and Azure.
    // AWS: GetSecretValue, DescribeSecret
    // GCP: accessSecretVersion, getSecretVersion
    // Azure: SecretGet, GetSecret, BackupSecret
    $cloud.target.resource.attribute.labels["operation"] = /^(GetSecretValue|DescribeSecret|accessSecretVersion|getSecretVersion|SecretGet|GetSecret|BackupSecret)$/ nocase

    // Alternatively match on resource type labels normalised by Chronicle UDM
    // for secrets manager resource categories across providers.
    $cloud.target.resource.resource_type = /secret|keyvault|secretmanager|secretsmanager/ nocase

    // Require a non-empty acting principal to exclude automated internal health checks
    // that arrive without an identity context.
    $cloud.principal.user.userid != ""

    // Exclude known-good service accounts and automation identities.
    not $cloud.principal.user.userid in %cloud_allowed_secrets_readers

    // Exclude internal platform service principals that perform routine
    // secret access as part of managed service operations.
    not $cloud.principal.user.userid = /^(aws-service-role|service-account@.*\.gserviceaccount\.com$)/ nocase

  outcome:
    $risk_score = max(75)
    $mitre_technique_id = array_distinct("T1555.006")
    $primary_entity = array_distinct($cloud.principal.user.userid)
    $accessed_secret = array_distinct($cloud.target.resource.name)
    $source_ip = array_distinct($cloud.principal.ip)

  condition:
    $cloud
}
